/**
 * debounce：延遲執行函式，直到停止呼叫後經過 wait 毫秒才真正執行。
 * @param {Function} fn - 要被防抖的函式
 * @param {number} wait - 等待時間（毫秒）
 * @param {boolean} [immediate=false] - 若為 true，第一次呼叫時立即執行，之後在靜默期內不再執行
 * @returns {Function} 防抖後的函式，附帶 cancel() 方法
 */
function debounce(fn, wait = 300, immediate = false) {
  let timer = null;

  const debounced = function (...args) {
    const context = this;
    const callNow = immediate && timer === null;

    clearTimeout(timer);

    timer = setTimeout(() => {
      timer = null;
      if (!immediate) {
        fn.apply(context, args);
      }
    }, wait);

    if (callNow) {
      fn.apply(context, args);
    }
  };

  debounced.cancel = function () {
    clearTimeout(timer);
    timer = null;
  };

  return debounced;
}

// ===== 使用範例 =====

// 1. 一般用法：輸入框搜尋，停止打字 500ms 後才送出請求
const searchInput = document.querySelector('#search');

const handleSearch = debounce((keyword) => {
  console.log('搜尋：', keyword);
  // fetch(`/api/search?q=${encodeURIComponent(keyword)}`)
}, 500);

searchInput?.addEventListener('input', (e) => {
  handleSearch(e.target.value);
});

// 2. 立即執行模式：第一次觸發立刻執行，之後 1 秒內的重複呼叫被忽略
const handleClick = debounce(() => {
  console.log('按鈕被點擊（立即執行）');
}, 1000, true);

// 3. 取消待執行的呼叫
const save = debounce(() => console.log('已儲存'), 2000);
save();
save.cancel(); // 取消，不會輸出「已儲存」
```

**說明：**
- **基本原理**：每次呼叫都會清除前一個計時器並重新設定，因此只有在「停止呼叫達 `wait` 毫秒」後才會執行一次。
- **`immediate` 參數**：設為 `true` 時，第一次呼叫會立即執行，之後的呼叫在靜默期內只會重置計時器。
- **`this` 與參數**：透過 `fn.apply` 保留原本的 `this` 與傳入的參數。
- **`cancel()`**：可手動取消尚未執行的呼叫，適用於元件卸載或表單重置等情境。

