/**
 * 建立一個防抖（debounce）函式：在最後一次呼叫後等待 delay 毫秒才執行。
 * @param {Function} fn 要防抖的函式
 * @param {number} delay 等待時間（毫秒）
 * @param {{ leading?: boolean }} [options] leading 為 true 時會在第一次呼叫時立即執行
 * @returns {Function & { cancel: () => void }}
 */
function debounce(fn, delay = 300, { leading = false } = {}) {
  let timer = null;

  function debounced(...args) {
    const callNow = leading && timer === null;

    clearTimeout(timer);

    timer = setTimeout(() => {
      timer = null;
      if (!leading) fn.apply(this, args);
    }, delay);

    if (callNow) fn.apply(this, args);
  }

  // 取消尚未執行的呼叫
  debounced.cancel = () => {
    clearTimeout(timer);
    timer = null;
  };

  return debounced;
}
```

### 使用範例

```javascript
// 模擬搜尋 API
function search(keyword) {
  console.log(`搜尋：${keyword}`);
}

const debouncedSearch = debounce(search, 500);

// 快速連續呼叫，只有最後一次會在停止輸入 500ms 後執行
debouncedSearch('j');
debouncedSearch('ja');
debouncedSearch('jav');
debouncedSearch('java');
// 輸出（約 500ms 後）：搜尋：java

// 立即執行版本：第一次呼叫立刻執行，之後的連續呼叫在停止 500ms 後才執行最後一次
const debouncedSave = debounce(() => console.log('已儲存'), 500, { leading: true });
debouncedSave(); // 立即輸出：已儲存
debouncedSave(); // 被忽略，直到停止呼叫 500ms 後才會再次觸發

// 取消尚未執行的呼叫
debouncedSearch('abc');
debouncedSearch.cancel(); // 不會執行 search('abc')
```

### 重點說明
- **防抖 vs 節流**：防抖是「停止呼叫一段時間後才執行」，適合搜尋輸入、視窗調整大小後重新計算等情境。
- **`this` 與參數保留**：使用 `...args` 與 `fn.apply(this, args)`，會保留原本的 `this` 與傳入參數。
- **`cancel()`**：可在元件卸載或不再需要時取消待執行的呼叫，避免記憶體或邏輯上的問題。

